script:
(function () {
  'use strict';
  // Debt-to-income ratio.
  //   Gross monthly income = annual amounts / 12 + monthly amounts.
  //   Front-end (housing) ratio = housing payment (rent or mortgage + property tax, insurance, HOA,
  //   mortgage insurance) / gross monthly income.
  //   Back-end (total) ratio = all monthly debt payments including housing / gross monthly income.
  // Thresholds below are widely used lending rules of thumb, not legal limits; each lender and
  // loan program sets its own.
  // Verified (scratchpad w2debt/dti.test.js): default example $72,000 a year = $6,000 a month;
  // housing $1,650 -> 27.5% front-end; $1,650 + $380 + $250 + $120 = $2,400 -> 40.0% back-end;
  // room under 36% = $2,160 - $2,400 = -$240; monthly vs yearly frequency gives identical ratios;
  // zero income and negative inputs show an error instead of a ratio.
  // ---- Common guideline thresholds (rules of thumb used across US mortgage lending) ----
  var GUIDES = [
    { label: 'Housing costs: 28% guideline', ratio: 0.28, housing: true },
    { label: 'All debts: 36% guideline', ratio: 0.36 },
    { label: 'All debts: 43% common lender cap', ratio: 0.43 },
    { label: 'All debts: 50% upper limit for some programs', ratio: 0.50 }
  ];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var raw = document.getElementById(id).value;
    if (String(raw).trim() === '') return 0;
    var v = parseFloat(raw);
    return isNaN(v) ? NaN : v;
  }

  function monthly(id) {
    var v = num(id), freq = document.getElementById(id + 'Freq');
    return freq && freq.value === 'year' ? v / 12 : v;
  }

  function ratios(income, housing, otherDebts) {
    var total = housing + otherDebts;
    return { front: housing / income, back: total / income, total: total };
  }

  function rating(back) {
    if (back <= 0.36) return { cls: 'callout-success', title: 'Within the common 36% guideline', text: 'Most lenders see a ratio at or below 36% as comfortable, and it usually leaves room in the budget for saving.' };
    if (back <= 0.43) return { cls: 'callout-note', title: 'Above 36% but within 43%', text: 'Many lenders still approve loans in this range, but there is less room for new debt or unexpected costs.' };
    if (back <= 0.50) return { cls: 'callout-warning', title: 'High: above 43%', text: 'Only some loan programs accept a ratio this high, usually with strong credit, savings or a large down payment.' };
    return { cls: 'callout-caution', title: 'Very high: above 50%', text: 'Half or more of your gross income goes to debt payments. Paying down balances or raising income would make borrowing much easier.' };
  }

  function pct(x) { return (x * 100).toFixed(1) + '%'; }

  function signedMoney(x) {
    if (Math.abs(x) < 0.005) return money.format(0);
    return (x > 0 ? '' : '−') + money.format(Math.abs(x));
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  function clearResults() {
    ['dtiBack', 'dtiFront', 'dtiIncomeOut', 'dtiDebtOut'].forEach(function (id) { set(id, '–'); });
    document.getElementById('dtiRating').hidden = true;
    clearBody('dtiGuides'); clearBody('dtiBreakdown');
  }

  function update() {
    var incomeIds = ['dtiIncome', 'dtiCoIncome', 'dtiOther'];
    var debtItems = [
      ['Rent or mortgage payment', 'dtiHousing'], ['Property tax, insurance and HOA', 'dtiHousingExtra'],
      ['Auto loans', 'dtiAuto'], ['Student loans', 'dtiStudent'], ['Credit card minimums', 'dtiCards'],
      ['Other loans and obligations', 'dtiOtherDebt']
    ];
    var values = {}, bad = false;
    incomeIds.concat(debtItems.map(function (d) { return d[1]; })).forEach(function (id) {
      var v = monthly(id);
      if (isNaN(v) || v < 0) bad = true;
      values[id] = v;
    });
    var income = values.dtiIncome + values.dtiCoIncome + values.dtiOther;
    var error = document.getElementById('dtiError');
    var problem = bad ? 'Enter amounts of $0 or more (leave a field blank or 0 if it does not apply).'
      : (income <= 0 ? 'Enter your gross income so the ratio can be calculated.' : '');
    error.hidden = !problem;
    error.textContent = problem;
    if (problem) { clearResults(); return; }

    var housing = values.dtiHousing + values.dtiHousingExtra;
    var other = values.dtiAuto + values.dtiStudent + values.dtiCards + values.dtiOtherDebt;
    var r = ratios(income, housing, other);
    set('dtiBack', pct(r.back));
    set('dtiFront', pct(r.front));
    set('dtiIncomeOut', money.format(income));
    set('dtiDebtOut', money.format(r.total));

    var rt = rating(r.back), box = document.getElementById('dtiRating');
    box.hidden = false;
    box.className = 'callout mt-5 ' + rt.cls;
    set('dtiRatingTitle', rt.title);
    set('dtiRatingText', rt.text);

    var g = clearBody('dtiGuides');
    GUIDES.forEach(function (guide) {
      var max = guide.ratio * income, yours = guide.housing ? housing : r.total;
      addRow(g, [guide.label, money.format(max), money.format(yours), signedMoney(max - yours)]);
    });

    var b = clearBody('dtiBreakdown');
    debtItems.forEach(function (d) {
      var v = values[d[1]];
      if (v > 0) addRow(b, [d[0], money.format(v), pct(v / income)]);
    });
    addRow(b, ['Total', money.format(r.total), pct(r.back)]);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('dtiForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
